  using namespace sprods_com_mod;

  auto zab2 = [&za, &zb](int j1, int j2, int j3, int j4) {
    return za(j1, j2) * zb(j2, j4) + za(j1, j3) * zb(j3, j4);
  };
  auto zba2 = [&za, &zb](int j1, int j2, int j3, int j4) {
    return zb(j1, j2) * za(j2, j4) + zb(j1, j3) * za(j3, j4);
  };
  auto zab = [&za, &zb](int j1, int j2, int j3) {
    return za(j1, j2) * zb(j2, j3);
  };
  auto za22a = [&za, &zab2](int j1, int j2, int j3, int j4, int j5, int j6) {
    return zab2(j1, j2, j3, j4) * za(j4, j6)
         + zab2(j1, j2, j3, j5) * za(j5, j6);
  };
  auto zb21b = [&zb, &zba2](int j1, int j2, int j3, int j4, int j5) {
