    +(std::pow((zb(j1,j3)*za(j4,j5)*t(j1,j2,j3)), 2) /(zb(j2,j3)*za(j5,j6)*std::pow(zab2(j4,j1,j2,j3), 3)*zab2(j4,j2,j3,j1)) -zab2(j4,j2,j3,j1)*std::pow(zab2(j5,j1,j2,j3), 2) /(zb(j2,j3)*za(j5,j6)*std::pow(zab2(j4,j1,j2,j3), 3))) *Lsm1_2mh(s(j3,j4),t(j1,j2,j3),s(j1,j2),s(j5,j6))
    -std::pow((za(j2,j3)*zb(j1,j6)), 2) /(zb(j5,j6)*t(j2,j3,j4)*za(j2,j4)*zab2(j4,j2,j3,j1)) *Lsm1(-s(j2,j3),-t(j2,j3,j4),-s(j3,j4),-t(j2,j3,j4))
    -0.5*zb(j1,j4)*(std::pow(za22a(j2,j1,j4,j2,j3,j5), 2) -std::pow(za(j2,j5), 2)*s(j1,j4)*s(j2,j3)) /(za(j1,j4)*zb(j2,j3)*za(j5,j6) *zab2(j2,j1,j4,j3)*zab2(j2,j3,j4,j1)) *i3m(s(j1,j4),s(j2,j3),s(j5,j6))
