5,j3,j4))*zb(j2,j6) -zab(j5,j1,j6)*zb(j2,j4)))) *i3m(s(j1,j2), s(j3,j4), s(j5,j6))
    +FFMPcc1(j1,j2,j3,j4,j5,j6,za,zb) *L0(-t(j2,j3,j4),-s(j3,j4))/s(j3,j4)
    +FFMPcc2(j1,j2,j3,j4,j5,j6,za,zb) *L0(-t(j2,j3,j4),-s(j5,j6))/s(j5,j6);

  return FFMPcc_unsym_result;
}

std::complex<double> FFMPcc1(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&za, &zb](int j1, int j2, int j3, int j4) {
    return za(j1, j2) * zb(j2, j4) + za(j1, j3) * zb(j3, j4);
  };

  std::complex<double> FFMPcc1_result =
    +2.*za(j2,j3)*zb(j2,j4)*zab2(j5,j2,j3,j4)*zab2(j5,j3,j4,j2)
    /(zb(j2,j3)*za(j5,j6)*t(j2,j3,j4)*zab2(j1,j3,j4,j2));

  return FFMPcc1_result;
}

std::complex<double> FFMPcc2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab2 = [&za, &zb](int j1, int j2, int j3, int j4) {
    return za(j1, j2) * zb(j2, j4) + za(j1, j3) * zb(j3, j4);
  };

  std::complex<double> FFMPcc2_result =
    -2.*zb(j1,j4)*zb(j2,j4)*za(j1,j5)*zab2(j5,j2,j3,j4)
    /(zb(j2,j3)*zb(j3,j4)*za(j5,j6)*zab2(j1,j3,j4,j2));

  return FFMPcc2_result;
}

}  // namespace

std::complex<double> FFMPcc(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  std::complex<double> FFMPcc_result;

  FFMPcc_result = FFMPcc_unsym(j1, j2, j3, j4, j5, j6, za, zb)
                + FFMPcc_unsym(j2, j1, j4, j3, j6, j5, zb, za);  // @coverage-probe

  return FFMPcc_result;
}

extern "C" {
  std::complex<double> FFMPcc_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* za_ptr, std::complex<double>* zb_ptr) {
    using namespace mxpart_mod;

    FArray2D<std::complex<double>> za(za_ptr, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(zb_ptr, mxpart, mxpart);

    return FFMPcc(j1, j2, j3, j4, j5, j6, za, zb);
  }
}

